#!/usr/bin/env python3
from __future__ import annotations
import json, os, re, urllib . parse, urllib . request
from typing import Any, Dict, List
import config

ROBOTICS_TERMS = ['robotics', 'robot', 'robots', 'embodied ai', 'embodied', 'bimanual', 'vla', 'sim2real', 'manipulation', 'manipulator', 'slam', 'rover', 'visuotactile', '6-dof', 'autonomous', 'lerobot', 'gr00t', 'humanoid', 'humanoids', 'locomotion', 'ros', 'ros2', 'isaac', 'mujoco', 'dexterous', 'teleoperation', 'mechatronics', 'kinematics', 'uav', 'lidar', 'actuation', 'physical intelligence', 'pi_0']
AI_TERMS = ['artificial intelligence', 'ai', 'machine learning', 'ml', 'deep learning', 'neural network', 'neural networks', 'llm', 'llms', 'vlm', 'vlms', 'vllm', 'triton', 'quantization', 'quantized', 'inference', 'kv-cache', 'pagedattention', 'agent', 'agents', 'agentic', 'multi-agent', 'mcp', 'evals', 'world model', 'world models', 'rag', 'fine-tuning', 'finetuning', 'lora', 'qlora', 'pytorch', 'tensorflow', 'jax', 'cuda', 'tensorrt', 'huggingface', 'hugging face', 'langchain', 'langgraph', 'llamaindex', 'llama_index', 'openai', 'anthropic', 'deepmind', 'transformer', 'transformers', 'diffusion', 'reinforcement learning', 'rlhf', 'grpo', 'computer vision', 'nlp', 'foundation model', 'foundation models', 'small language model', 'slm', 'knowledge distillation', 'alphageometry']
CS_CONTEXT_TERMS = ['phd', 'research scientist', 'researcher', 'scientist', 'professor', 'engineer', 'engineering', 'developer', 'open-source', 'open source', 'github', 'arxiv', 'paper', 'benchmark', 'benchmarks', 'latency', 'throughput', 'distributed', 'infrastructure', 'infra', 'runtime', 'compiler', 'kernel', 'kernels', 'python', 'c++', 'rust', 'founder', 'co-founder', 'cto', 'pilot', 'models', 'policies', 'gpu', 'gpus', 'neuro-symbolic', 'multimodal']
NON_TECH_TERMS = ['minecraft', 'youtuber', 'twitch', 'streamer', 'dream smp', 'esports', 'fortnite', 'valorant', 'roblox', 'vlogger', 'tiktoker', 'makeup', 'fashion', 'beauty', 'astrology', 'horoscope', 'football', 'soccer', 'nba', 'nfl', 'singer', 'actor', 'actress', 'fan account', 'stan account', 'parody', 'gamer']
SPAM_TERMS = ['memecoin', 'airdrop', '100x', 'paid promo', '$aibot', 'presale', 'nft giveaway', 'crypto pump', 'casino', 'betting']
SEA_TERMS = ['vietnam', 'vietnamese', 'ho chi minh', 'hcmc', 'hanoi', 'da nang', 'singapore', 'nus', 'ntu', 'hcmut', 'hcmus', 'jakarta', 'indonesia', 'malaysia', 'kuala lumpur', 'thailand', 'bangkok', 'philippines', 'manila', 'sea', 'asean', 'southeast asia']
HOOK_TERMS = ['pilot', 'design-partner', 'pre-seed', 'open-source', 'open source', 'benchmarked', 'benchmark', 'field-tested', 'shipped', 'shipping', 'testing', 'collaboration', 'discussions', 'released', 'building', 'co-founder', 'founder', 'lead', 'scientist', 'researcher', 'author', 'creator']

def _match_terms(text: str, terms: List[str]) -> List[str]: low = (text or '') . lower(); return [t for t in terms if re . search(r'(?<![a-z0-9_])' + re . escape(t . lower()) + r'(?![a-z0-9_])', low)]

def classify_archetype(combined: str, mr: List[str], ma: List[str], mcs: List[str], non_tech: List[str]) -> str: return 'Noise / Promo' if _match_terms(combined, SPAM_TERMS) else ('Out of Scope (Non-AI/Robotics)' if ((not mr and not ma) or (non_tech and (len(mr) + len(ma) <= 1) and not mcs)) else ('Founder / Spinout Builder' if _match_terms(combined, ['founder', 'co-founder', 'spinning this out', 'pre-seed', 'ceo']) else ('AI & Robotics Researcher' if _match_terms(combined, ['phd', 'research scientist', 'paper', 'nus', 'hcmut', 'hcmus', 'diffusion', 'lab', 'scientist', 'professor', 'deepmind']) else ('AI Infra / Systems Engineer' if _match_terms(combined, ['vllm', 'triton', 'kv-cache', 'mcp', 'infra', 'infrastructure', 'runtime', 'engineer', 'developer', 'evals']) else 'AI & Robotics Builder'))))

def evaluate_candidate_fit(candidate: Dict[str, Any], query_segment: str) -> Dict[str, Any]: uname = config . extract_x_handle(candidate . get('username', '')); bio_l = (candidate . get('bio') or '') . lower(); loc_l = (candidate . get('location') or '') . lower(); posts = candidate . get('recent_posts') or []; posts_txt = ' ' . join(p . get('text', '') for p in posts) . lower(); combined = f'{bio_l} {loc_l} {posts_txt}' . strip(); best_post = posts[0] if posts else {'text': candidate . get('bio', ''), 'url': f'{config . X_WEB}/{uname}'}; ev_quote = best_post . get('text', '') or candidate . get('bio', '') or f'Profile @{uname} on X (No AI/Robotics bio or posts found).'; ev_url = best_post . get('url', f'{config . X_WEB}/{uname}'); spam_hits = _match_terms(combined, SPAM_TERMS); mr = _match_terms(combined, ROBOTICS_TERMS); ma = _match_terms(combined, AI_TERMS); mcs = _match_terms(combined, CS_CONTEXT_TERMS); non_tech = _match_terms(combined, NON_TECH_TERMS); msea = _match_terms(combined, SEA_TERMS); mh = _match_terms(combined, HOOK_TERMS); archetype = classify_archetype(combined, mr, ma, mcs, non_tech); is_out = (not mr and not ma) or (bool(non_tech) and (len(mr) + len(ma) <= 1) and not mcs); is_weak = (not is_out) and ((len(mr) + len(ma) == 1) and not mcs); tech = 0 if (spam_hits or is_out) else (10 if is_weak else min(35, 12 + 6 * len(mr) + 5 * len(ma) + 2 * min(4, len(mcs)))); sea = 0 if (spam_hits or is_out) else (6 if is_weak else (25 if len(msea) >= 2 else (21 if len(msea) == 1 else (15 if (len(mr) + len(ma) >= 3 or len(mcs) >= 2) else 8)))); readiness = 0 if spam_hits else (4 if is_out else (6 if is_weak else (min(25, 10 + 4 * len(mh)) if mh else 8))); has_quant = bool(re . search(r'\b(\d+([.]\d+)?(ms|x|%|gb|tb|dof|ha|hrs|hours|\$))\b', combined)); q_toks = [tok . strip() . lower() for tok in query_segment . replace(',', ' ') . split() if len(tok . strip()) > 2]; q_hits = [tok for tok in q_toks if tok in combined]; snr = 5 if spam_hits else (4 if (is_out and non_tech) else (8 if is_out else (6 if is_weak else min(15, 9 + (3 if has_quant else 0) + min(3, len(q_hits)) + (2 if len(mcs) >= 2 else 0))))); total = min(99, tech + sea + readiness + snr); r_list = (['Excluded (Noise Filter): Promotional token/airdrop pattern detected.'] if spam_hits else ([f'Excluded (Out of Domain): Non-AI/Robotics profile ({", " . join(non_tech[:3])}) with zero AI/Robotics engineering signals.' if non_tech else 'Excluded (Out of Domain): No verifiable AI, Machine Learning, or Robotics signals found in profile bio or recent posts.'] if is_out else ([f'Insufficient Technical Depth: Only isolated mention ({(mr + ma)[0]}) without engineering or research context.'] if is_weak else ([f'Embodied AI / Robotics depth ({", " . join(mr[:4])})'] if mr else []) + ([f'AI / ML / Agentic systems signal ({", " . join(ma[:4])})'] if ma else []) + ([f'Southeast Asia ecosystem footprint ({candidate . get("location") or ", " . join(msea[:2])})'] if msea else ['Global AI & Robotics ecosystem builder']) + ([f'Active builder / research hook ({", " . join(mh[:3])})'] if mh else [])))); return {'fit_score': total, 'role_archetype': archetype, 'score_breakdown': {'technical_depth': tech, 'sea_ecosystem_fit': sea, 'conversation_readiness': readiness, 'signal_to_noise': snr}, 'fit_reasons': r_list, 'evidence_quote': ev_quote, 'evidence_url': ev_url}

def verify_dm_grounding(draft_dm: str, candidate: Dict[str, Any]) -> Dict[str, Any]: text = (draft_dm or '') . strip(); lower_dm = text . lower(); ev_txt = f"{candidate . get('bio', '')} {candidate . get('evidence_quote', '')} {candidate . get('username', '')}" . lower(); ev_tokens = {tok for tok in re . findall(r'[a-z0-9_-]{3,}', ev_txt) if tok not in {'just', 'with', 'from', 'that', 'this', 'have', 'looking', 'building', 'open', 'across', 'the', 'and', 'for', 'our'}}; matched = [tok for tok in ev_tokens if tok in lower_dm]; has_anchor = len(matched) >= 1 and not text . startswith('[Out of Scope'); cliches = [c for c in config . BANNED_CLICHES if c in lower_dm]; no_cliche = len(cliches) == 0; has_q = '?' in text; len_ok = 50 <= len(text) <= 480; no_links = not bool(re . search(config . SCHEME + '?' + ':' + '//', text)); checks = [{'rule': 'Evidence Anchor', 'passed': has_anchor, 'detail': f'Matched tokens: {", " . join(matched[:4])}'}, {'rule': 'Zero Invented Familiarity', 'passed': no_cliche, 'detail': 'No fake flattery cliches'}, {'rule': 'Conversational Question Hook', 'passed': has_q, 'detail': 'Ends with question (?)'}, {'rule': 'Optimal DM Length (50-480 chars)', 'passed': len_ok, 'detail': f'{len(text)} chars'}, {'rule': 'Link-Free Cold DM Policy', 'passed': no_links, 'detail': 'No URLs in cold DM'}]; passed = sum(1 for c in checks if c['passed']); return {'all_passed': (passed == len(checks)) and not text . startswith('[Out of Scope'), 'score_label': 'Out of Scope (Filtered)' if text . startswith('[Out of Scope') else f'{passed}/{len(checks)} Checks Passed', 'matched_anchors': matched[:5], 'checks': [] if text . startswith('[Out of Scope') else checks}

def generate_grounded_dm(candidate: Dict[str, Any], gemini_key: str = '', sender_context: str = 'GenAI Fund') -> str: uname = config . extract_x_handle(candidate . get('username', '')); fit_score = int(candidate . get('fit_score', 0)); raw_name = candidate . get('display_name', '') or uname or 'there'; first_name = raw_name . split('|')[0] . replace('Dr.', '') . strip() . split()[0] if raw_name else 'there'; ev_quote = (candidate . get('evidence_quote') or candidate . get('bio') or '') . strip(); short_ev = (ev_quote[:110] + '...') if len(ev_quote) > 110 else (ev_quote or f'your AI & robotics work on @{uname}'); return f'[Out of Scope — Fit Score {fit_score}/100] @{uname} does not show verifiable AI or Robotics engineering evidence. Outreach DM disabled by quality gate.' if fit_score < 50 else f"Hi {first_name} — came across your work on @{uname} ('{short_ev}'). At GenAI Fund we partner with technical AI and robotics builders on enterprise pilots and ecosystem growth across Southeast Asia and globally. What technical milestones or deployment bottlenecks are you focusing on next?"

def classify_reply_intent(reply_text: str) -> Dict[str, Any]: low = (reply_text or '') . lower(); is_opt = any(k in low for k in ['unsubscribe', 'not interested', 'stop', 'remove me']); is_warm = ('?' in (reply_text or '')) or any(k in low for k in ['call', 'chat', 'pilot', 'deck', 'next week', 'tuesday', 'thursday', 'sure', 'interested', 'coffee', 'zoom', 'meet', 'yes']); return {'reply_intent': 'opt_out', 'prospect_status': 'blocked', 'needs_attention': 0, 'attention_reason': 'Opt-out requested — moved to Blocked'} if is_opt else ({'reply_intent': 'warm_interest_or_question', 'prospect_status': 'needs_attention', 'needs_attention': 1, 'attention_reason': 'High-Priority Warm Reply — Ready for FDE Partner takeover'} if is_warm else {'reply_intent': 'general_reply', 'prospect_status': 'replied', 'needs_attention': 1, 'attention_reason': 'Inbound reply received — review thread'})
